def replace_element(text, tag, marker, replacement):
    anchor=text.find(marker)
    if anchor<0: raise RuntimeError(f'replacement marker not found: {marker}')
    start=text.rfind('<'+tag,0,anchor); depth=0
    for match in re.finditer(fr'</?{tag}\b[^>]*>',text[start:]):
        depth += -1 if match.group(0).startswith('</') else 1
        if depth==0:
            return text[:start]+replacement+text[start+match.end():]
    raise RuntimeError(f'unbalanced replacement {tag}: {marker}')

